const __pageData = JSON.parse('{"title":"第 3 章：张量、形状与内存","description":"检查 shape、stride、广播和矩乘，理解复制与设备迁移。","frontmatter":{"title":"第 3 章：张量、形状与内存","description":"检查 shape、stride、广播和矩乘，理解复制与设备迁移。","pageClass":"burn-course"},"headers":[],"relativePath":"burn/tensors-and-memory.md","filePath":"burn/tensors-and-memory.md"}');
